            Path actual = lexical.toRealPath();
            boolean regularDirect = Files.isRegularFile(actual)
                    && actual.getParent() != null && actual.getParent().equals(realFolder);
            return new EntryPath(lexical, actual, true, regularDirect);
        } catch (NoSuchFileException e) {
