        }

        List<String> getViolations(ArchRule rule) {
            return ensureUnixLineBreaks(store.getViolations(rule));
        }

        void save(ArchRule rule, List<String> violations) {
            store.save(rule, ensureUnixLineBreaks(violations));
        }
    }

