+    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean constructorStrategyWasGiven;
+
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private IntegrityMode integrityMode;
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private FileSyncedProperties storedRules;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
+     *
+     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+        constructorStrategyWasGiven = false;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        checkArgument(ruleViolationFileNameStrategy != null, "Rule violation file name strategy must not be null");
+        constructorStrategy = ruleViolationFileNameStrategy;
+        constructorStrategyWasGiven = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        ruleViolationFileNameStrategy = selectFileNameStrategy(properties);
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity mode '%s' requires %s=true", IntegrityMode.REPAIR.value, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        File storedRulesFile = getStoredRulesFile();
+        String stateKey;
+        try {
+            stateKey = storedRulesFile.getCanonicalPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        FileSyncedProperties state = STORED_RULES_BY_PATH.computeIfAbsent(stateKey, ignored -> new FileSyncedProperties(storedRulesFile));
+
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
+        synchronized (state) {
+            initializeLocked(state, storedRulesFile);
+        }
+        storedRules = state;
+    }
+
+    private RuleViolationFileNameStrategy selectFileNameStrategy(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (constructorStrategyWasGiven) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured when a custom RuleViolationFileNameStrategy was supplied to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+        if (configured == null || FILE_NAMES_RANDOM.equals(configured)) {
+            return ignored -> UUID.randomUUID().toString();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::descriptionFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            Object strategy = strategyType.getConstructor().newInstance();
+            if (!(strategy instanceof RuleViolationFileNameStrategy)) {
+                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
+            }
+            return (RuleViolationFileNameStrategy) strategy;
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured through %s='%s' (a public no-argument constructor is required)",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private IntegrityMode parseIntegrity(String configured) {
+        for (IntegrityMode mode : IntegrityMode.values()) {
+            if (mode.value.equals(configured)) {
+                return mode;
+            }
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid value '%s' for %s; accepted values are repair, fail and ignore",
+                configured, INTEGRITY_PROPERTY_NAME));
+    }
+
+    private File getStoredRulesFile() {
+        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+        if (!fileSystemEntryExists(rulesFile.toPath()) && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        return rulesFile;
+    }
+
+    private void initializeLocked(FileSyncedProperties state, File storedRulesFile) {
+        Path folder = storeFolder.toPath();
+        boolean indexExists = fileSystemEntryExists(storedRulesFile.toPath());
+        try {
+            if (!fileSystemEntryExists(folder)) {
+                if (!storeCreationAllowed) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                            ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+                }
+                Files.createDirectories(folder);
+            }
+            if (!Files.isDirectory(folder)) {
+                throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", folder));
+            }
+            if (indexExists && !Files.isRegularFile(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "The stored rules index is not a regular file directly in the store folder: %s", storedRulesFile));
+            }
+            Path realFolder = folder.toRealPath();
+
+            Properties loaded;
+            if (indexExists) {
+                loaded = state.loadProperties();
+            } else {
+                loaded = new Properties();
+            }
+
+            if (integrityMode == IntegrityMode.FAIL) {
+                IntegrityReport report = inspect(loaded, folder, realFolder, storedRulesFile.toPath());
+                if (!report.isClean()) {
+                    throw new StoreInitializationFailedException(report.asMessage(storedRulesFile));
+                }
+                if (!indexExists) {
+                    state.writeProperties(loaded);
+                }
+            } else if (integrityMode == IntegrityMode.REPAIR) {
+                IntegrityReport report = inspect(loaded, folder, realFolder, storedRulesFile.toPath());
+                repair(report, loaded, folder, realFolder, storedRulesFile.toPath());
+                if (report.changed) {
+                    state.writeProperties(loaded);
+                } else if (!indexExists) {
+                    // A newly created empty index is a necessary part of a successfully initialized store.
+                    state.writeProperties(loaded);
+                }
+            } else if (!indexExists) {
+                state.writeProperties(loaded);
+            }
+            state.replaceLoadedProperties(loaded);
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        FileSyncedProperties state = requireInitialized();
+        synchronized (state) {
+            return state.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        FileSyncedProperties state = requireInitialized();
+        synchronized (state) {
+            saveLocked(state, rule, violations);
+        }
+    }
+
+    private void saveLocked(FileSyncedProperties state, ArchRule rule, List<String> violations) {
+        String description = rule.getDescription();
+        String recordedName = state.getProperty(description);
+        boolean knownRule = recordedName != null;
+
+        if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && !knownRule) {
+            return;
+        }
+
+        if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && knownRule) {
+            removeRuleWithFile(state, description, recordedName);
+            return;
+        }
+
+        String ruleFileName = knownRule ? recordedName : requireRuleFileName(description, true);
+        validateWriteTarget(state, description, ruleFileName, knownRule);
+        FileWriteResult writeResult = write(violations, storeFolder.toPath().resolve(toDirectPath(ruleFileName)));
+
+        if (!knownRule) {
+            Properties updated = copyOf(state.properties());
+            updated.setProperty(description, ruleFileName);
+            try {
+                state.writeProperties(updated);
+            } catch (RuntimeException e) {
+                if (writeResult.created) {
+                    deleteQuietly(storeFolder.toPath().resolve(toDirectPath(ruleFileName)));
+                }
+                throw e;
+            }
+            state.replaceLoadedProperties(updated);
+        }
+    }
+
+    private void removeRuleWithFile(FileSyncedProperties state, String description, String recordedName) {
+        Properties current = state.properties();
+        boolean shared = isShared(description, recordedName, current);
+        if (isIndexFile(recordedName)) {
+            throw new StoreUpdateFailedException("A rule violation file name must not lead to the stored.rules index");
+        }
+        if (!shared) {
+            deleteNamedFile(recordedName);
+        }
+        Properties updated = copyOf(current);
+        updated.remove(description);
+        try {
+            state.writeProperties(updated);
+        } catch (RuntimeException e) {
+            throw e;
+        }
+        state.replaceLoadedProperties(updated);
+    }
+
+    private boolean isShared(String description, String name, Properties properties) {
+        List<String> descriptions = new ArrayList<>(properties.stringPropertyNames());
+        for (String otherDescription : descriptions) {
+            if (!description.equals(otherDescription) && name.equals(properties.getProperty(otherDescription))) {
+                return true;
+            }
+        }
+        EntryPath first = resolveEntryPath(name);
+        if (first.actual == null) {
+            return false;
+        }
+        for (String otherDescription : descriptions) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            EntryPath other = resolveEntryPath(properties.getProperty(otherDescription));
+            if (other.actual != null && sameFile(first.actual, other.actual)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        FileSyncedProperties state = requireInitialized();
+        synchronized (state) {
+            String ruleDetailsFileName = state.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (isOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .filter(line -> !"\r".equals(line))
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return new String(toByteArray(storeFolder.toPath().resolve(toDirectPath(fileName)).toFile()), StandardCharsets.UTF_8);
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private FileWriteResult write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        byte[] content = builder.toString().getBytes(StandardCharsets.UTF_8);
+        try {
+            boolean alreadyExists = fileSystemEntryExists(ruleDetails);
+            if (alreadyExists) {
+                Files.write(ruleDetails, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+                return new FileWriteResult(false);
+            }
+            Path temporary = Files.createTempFile(storeFolder.toPath(), ".rule-write-", ".tmp");
+            try {
+                Files.write(temporary, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+                moveReplacing(temporary, ruleDetails);
+                return new FileWriteResult(true);
+            } finally {
+                deleteQuietly(temporary);
+            }
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String requireRuleFileName(String ruleDescription, boolean update) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
+        } catch (RuntimeException e) {
+            if (update) {
+                throw new StoreUpdateFailedException(e);
+            }
+            throw new StoreInitializationFailedException(e);
+        }
+        if (result == null || result.isEmpty()) {
+            String message = String.format("RuleViolationFileNameStrategy returned no file name for rule '%s'", ruleDescription);
+            if (update) {
+                throw new StoreUpdateFailedException(message);
+            }
+            throw new StoreInitializationFailedException(message);
+        }
+        return result;
+    }
+
+    private void validateWriteTarget(FileSyncedProperties state, String description, String name, boolean knownRule) {
+        Path relative = directPathOrNull(name);
+        if (relative == null) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name '%s' is not a direct file in the store folder", name));
+        }
+        if (knownRule && !name.equals(state.getProperty(description))) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule '%s' does not record rule violation file name '%s'", description, name));
+        }
+        if (!knownRule && state.properties().stringPropertyNames().stream()
+                .anyMatch(otherDescription -> name.equals(state.getProperty(otherDescription)))) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name '%s' is recorded by another rule", name));
+        }
+        Path target = storeFolder.toPath().resolve(relative);
+        Path index = storeFolder.toPath().resolve(STORED_RULES_FILE_NAME);
+        if (isIndexFile(name) || sameFile(target, index)) {
+            throw new StoreUpdateFailedException("A rule violation file name must not lead to the stored.rules index");
+        }
+        if (fileSystemEntryExists(target)) {
+            try {
+                Path realFolder = storeFolder.toPath().toRealPath();
+                Path realTarget = target.toRealPath();
+                if (!realTarget.getParent().equals(realFolder) || !Files.isRegularFile(realTarget)) {
+                    throw new StoreUpdateFailedException(String.format(
+                            "Rule violation file name '%s' does not lead directly into the store folder", name));
+                }
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+    }
+
+    private void deleteNamedFile(String name) {
+        Path path = directPathOrNull(name);
+        if (path == null) {
+            return;
+        }
+        Path named = storeFolder.toPath().resolve(path);
+        try {
+            Path target = named.toRealPath();
+            Files.deleteIfExists(named);
+            if (!samePath(named, target)) {
+                Files.deleteIfExists(target);
+            }
+        } catch (NoSuchFileException e) {
+            // A broken entry has no file to remove.
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(String.format("Could not delete rule violation file '%s'", name), e);
+        }
+    }
+
+    private IntegrityReport inspect(Properties properties, Path folder, Path realFolder, Path index) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String name = properties.getProperty(description);
+            String derived = requireRuleFileName(description, false);
+            EntryPath path = resolveEntryPath(folder, realFolder, name);
+            boolean broken = !path.isRegularFileDirectlyInFolder;
+            boolean resolved = !broken && isResolved(path.actual);
+            entries.add(new Entry(description, name, derived, path, broken, resolved));
+        }
+
+        Map<String, List<Entry>> byRecordedName = groupBy(entries, entry -> entry.name);
+        Set<Entry> shared = new HashSet<>();
+        for (List<Entry> sameName : byRecordedName.values()) {
+            if (sameName.size() > 1) {
+                shared.addAll(sameName);
+            }
+        }
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry left = entries.get(i);
+                Entry right = entries.get(j);
+                if (left.path.actual != null && right.path.actual != null && sameFile(left.path.actual, right.path.actual)) {
+                    shared.add(left);
+                    shared.add(right);
+                }
+            }
+        }
+        for (Entry entry : entries) {
+            entry.shared = shared.contains(entry);
+            entry.misplaced = !entry.name.equals(entry.derived);
+            entry.colliding = false;
+        }
+        Map<String, List<Entry>> byDerivedName = groupBy(entries, entry -> entry.derived);
+        for (List<Entry> sameDerivedName : byDerivedName.values()) {
+            if (sameDerivedName.size() > 1) {
+                for (Entry entry : sameDerivedName) {
+                    entry.colliding = true;
+                }
+            }
+        }
+        for (Entry entry : entries) {
+            entry.occupied = entry.misplaced && isOccupied(entry, entries, folder, realFolder);
+        }
+
+        List<Path> unowned = findUnownedFiles(entries, folder, index);
+        return new IntegrityReport(entries, unowned);
+    }
+
+    private boolean isOccupied(Entry entry, List<Entry> entries, Path folder, Path realFolder) {
+        Path derivedPath = directPathOrNull(entry.derived);
+        if (derivedPath == null) {
+            return true;
+        }
+        for (Entry other : entries) {
+            if (other != entry && entry.derived.equals(other.name)) {
+                return true;
+            }
+        }
+        Path candidate = folder.resolve(derivedPath);
+        if (fileSystemEntryExists(candidate)) {
+            return true;
+        }
+        try {
+            Path realCandidate = candidate.toRealPath();
+            return !realCandidate.getParent().equals(realFolder);
+        } catch (NoSuchFileException e) {
+            return false;
+        } catch (IOException e) {
+            return true;
+        }
+    }
+
+    private List<Path> findUnownedFiles(List<Entry> entries, Path folder, Path index) {
+        List<Path> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(folder)) {
+            for (Path file : files) {
+                if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS) || sameFile(file, index)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (entry.path.actual != null && sameFile(file, entry.path.actual)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private void repair(IntegrityReport report, Properties properties, Path folder, Path realFolder, Path index) {
+        for (Entry entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                properties.remove(entry.description);
+            } else if (entry.resolved) {
+                deleteResolvedEntryFile(entry);
+                properties.remove(entry.description);
+            }
+        }
+        for (Entry entry : report.entries) {
+            if (entry.shared || entry.broken || entry.resolved || !entry.misplaced || entry.colliding || entry.occupied) {
+                continue;
+            }
+            moveEntryFile(entry, folder, realFolder);
+            properties.setProperty(entry.description, entry.derived);
+        }
+        report.changed = !properties.equals(report.originalProperties);
+    }
+
+    private void deleteResolvedEntryFile(Entry entry) {
+        if (entry.path.actual == null) {
+            return;
+        }
+        try {
+            Files.deleteIfExists(entry.path.lexical);
+            if (!samePath(entry.path.lexical, entry.path.actual)) {
+                Files.deleteIfExists(entry.path.actual);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not delete resolved rule violation file '%s'", entry.name), e);
+        }
+    }
+
+    private void moveEntryFile(Entry entry, Path folder, Path realFolder) {
+        Path destination = folder.resolve(toDirectPath(entry.derived));
+        Path source = entry.path.actual;
+        try {
+            moveReplacing(source, destination);
+            if (!samePath(entry.path.lexical, source)) {
+                Files.deleteIfExists(entry.path.lexical);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not move rule violation file '%s' to '%s'", entry.name, entry.derived), e);
+        }
+    }
+
+    private FileSyncedProperties requireInitialized() {
+        if (storedRules == null || storeFolder == null) {
+            throw new IllegalStateException("Violation store has not been initialized");
+        }
+        return storedRules;
+    }
+
+    private static String descriptionFileName(String description) {
+        String normalizedDescription = description.replace("\r\n", "\n");
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(normalizedDescription);
+        String word = matcher.find() ? matcher.group(1) : "rule";
+        return word + "-" + sha256(normalizedDescription);
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte part : digest) {
+                result.append(String.format("%02x", part & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private static boolean isOnlyLineBreaks(String text) {
+        if (text.isEmpty()) {
+            return true;
+        }
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character != '\n' && character != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private EntryPath resolveEntryPath(String name) {
+        try {
+            Path folder = storeFolder.toPath();
+            return resolveEntryPath(folder, folder.toRealPath(), name);
+        } catch (IOException e) {
+            return new EntryPath(null, null, false, false);
+        }
+    }
+
+    private EntryPath resolveEntryPath(Path folder, Path realFolder, String name) {
+        Path relative = directPathOrNull(name);
+        if (relative == null) {
+            return new EntryPath(null, null, false, false);
+        }
